contact=pagehero('Get in touch','Let’s talk hair.<br><em>Or your next chapter.</em>','Book some time for yourself, ask about a service or find out more about training. We’d love to hear from you.')
contact+=f'''<section class="section pt-0"><div class="wrap contact-grid"><div class="contact-cards"><div class="contact-card"><h3>Ready for an appointment?</h3><p>See current services, prices and availability in the online booking system.</p>{button('Book an appointment',BOOK,external=True)}</div><div class="contact-card"><h3>Prefer to say hello?</h3><p>For service questions, consultations and academy enquiries.</p><a class="email" href="mailto:thesnippitypip@hotmail.com">thesnippitypip@hotmail.com</a></div><div class="contact-card"><h3>Find us in Saltash.</h3><p>The Snippitypip is based in Saltash, Cornwall. Your appointment details will confirm where to come.</p><div class="socials"><a href="https://www.instagram.com/thesnippitypip/" target="_blank" rel="noopener noreferrer">Instagram <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a><a href="https://www.facebook.com/p/Thesnippitypip-100064112289747/" target="_blank" rel="noopener noreferrer">Facebook <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a><a href="https://www.tiktok.com/@thesnippitypip" target="_blank" rel="noopener noreferrer">TikTok <img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></a></div></div></div><div class="form-panel"><h3>Start a conversation.</h3><p class="small muted">A little about you and what you have in mind.</p><form id="enquiry-form"><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="email">Your email</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="160"></div><div class="field"><label for="interest">I’m interested in</label><select id="interest" name="interest"><option>Hair appointment</option><option>Consultation</option><option>Cutting &amp; styling</option><option>Hair colouring</option><option>Blow dries &amp; styling</option><option>Wedding hair</option><option>Occasion hair</option><option>Hair extensions</option><option>Scalp therapy</option><option>Mesh integration</option><option>Haircare &amp; GLOWWA</option><option>Training academy</option><option>Something else</option></select></div><div class="field"><label for="message">Your message</label><textarea id="message" name="message" placeholder="Tell us a little about what you’re looking for…" required maxlength="3000"></textarea></div><p class="form-help">This opens a draft in your email app for you to send. Your message is not submitted or stored by this website. Please keep sensitive health information for your private consultation.</p><button class="btn" type="submit">Create email enquiry <span aria-hidden="true"><img class="action-sunflower" src="/assets/sunflower.svg" width="18" height="18" alt="" aria-hidden="true"></span></button><p class="form-status" id="form-status" role="status" aria-live="polite"></p><button id="copy-message" class="text-link" type="button" hidden>Copy message</button></form></div></div></section>'''
